  it('exports list_sessions and session_list as members of the public message unions', () => {
    const result = validateMessage({type: 'list_sessions', userId: 'another-user'});
    const request: ListSessionsMessage | undefined =
      result.valid && result.data.type === 'list_sessions' ? result.data : undefined;
